7	function parseArgs(args: string[]): { command: string; contentDir: string; outputDir: string; templatesDir: string; port: number } {
8	  let command = 'build';
9	  let contentDir = './content';
10	  let outputDir = './dist';
11	  let templatesDir = './templates';
12	  let port = 3000;
13	
14	  for (let i = 0; i < args.length; i++) {
15	    const arg = args[i];
16	
17	    if (!arg.startsWith('-')) {
18	      command = arg;
19	      continue;
20	    }
21	
22	    if (arg === '--content' && i + 1 < args.length) {
23	      contentDir = args[++i];
24	    } else if (arg === '--output' && i + 1 < args.length) {
25	      outputDir = args[++i];
26	    } else if (arg === '--templates' && i + 1 < args.length) {
27	      templatesDir = args[++i];
28	    } else if (arg === '--port' && i + 1 < args.length) {
29	      port = parseInt(args[++i], 10);
30	    }
31	  }
32	
33	  return { command, contentDir, outputDir, templatesDir, port };
34	}
35	
36	async function main(): Promise<void> {
37	  const args = process.argv.slice(2);
38	  const { command, contentDir, outputDir, templatesDir, port } = parseArgs(args);
39	
40	  const resolvedContentDir = path.resolve(contentDir);
41	  const resolvedOutputDir = path.resolve(outputDir);
42	  const resolvedTemplatesDir = path.resolve(templatesDir);
43	
44	  try {
45	    if (command === 'build') {
46	      const generator = new SiteGenerator({
47	        contentDir: resolvedContentDir,
48	        outputDir: resolvedOutputDir,
49	        templatesDir: resolvedTemplatesDir,
50	      });
51	
52	      await generator.build();
53	    } else if (command === 'serve') {
54	      const devServer = new DevServer({
55	        contentDir: resolvedContentDir,
56	        outputDir: resolvedOutputDir,
57	        templatesDir: resolvedTemplatesDir,
58	        port,
59	      });
60	
61	      await devServer.start();
62	
63	      process.on('SIGINT', async () => {
64	        console.log('\nShutting down server...');
65	        await devServer.stop();
66	        process.exit(0);
67	      });
68	    } else {
69	      console.error(`Unknown command: ${command}`);
70	      process.exit(1);
71	    }
72	  } catch (error) {
73	    console.error('Error:', error instanceof Error ? error.message : String(error));
74	    process.exit(1);
75	  }
76	}
