7	export class SiteGenerator {
8	  private contentDir: string;
9	  private outputDir: string;
10	  private templatesDir: string;
11	  private templateEngine: TemplateEngine | null = null;
12	
13	  constructor(options: BuildOptions) {
14	    this.contentDir = options.contentDir;
15	    this.outputDir = options.outputDir;
16	    this.templatesDir = options.templatesDir || './templates';
17	    if (fs.existsSync(this.templatesDir)) {
18	      this.templateEngine = new TemplateEngine(this.templatesDir);
19	    }
20	  }
21	
22	  private ensureDir(dirPath: string): void {
23	    if (!fs.existsSync(dirPath)) {
24	      fs.mkdirSync(dirPath, { recursive: true });
25	    }
26	  }
27	
28	  private getMarkdownFiles(): string[] {
29	    if (!fs.existsSync(this.contentDir)) {
30	      return [];
31	    }
32	
33	    return fs
34	      .readdirSync(this.contentDir)
35	      .filter((file) => file.endsWith('.md'))
36	      .sort();
37	  }
38	
39	  private renderPageWithTemplate(
40	    title: string,
41	    content: string,
42	    templateName?: string,
43	    layoutName?: string,
44	    data?: Record<string, unknown>
45	  ): string {
46	    if (!this.templateEngine) {
47	      return this.generatePageHtml(title, content);
48	    }
49	
50	    const pageData = {
51	      title: this.escapeHtml(title),
52	      content,
53	      ...data,
54	    };
55	
56	    const template = templateName || 'page';
57	    const layout = layoutName || 'default';
58	
59	    try {
60	      if (this.templateEngine.hasLayout(layout)) {
61	        return this.templateEngine.renderPageTemplate(template, pageData, layout);
62	      }
63	    } catch {
64	      // Fall back to default HTML if template rendering fails
65	    }
66	
67	    return this.generatePageHtml(title, content);
68	  }
