116	  private generateIndexHtml(pages: PageMetadata[]): string {
117	    const pagesList = pages
118	      .map(
119	        (page) => `    <li>
120	      <a href="${this.escapeHtml(page.url)}">${this.escapeHtml(page.title)}</a>
121	      ${page.date ? `<span style="color: #666; margin-left: 10px;">${this.escapeHtml(page.date)}</span>` : ''}
122	      ${page.tags.length > 0 ? `<div style="margin-top: 5px;"><small>${page.tags.map((tag) => `<span style="display: inline-block; background: #eee; padding: 2px 8px; border-radius: 3px; margin-right: 5px;">${this.escapeHtml(tag)}</span>`).join('')}</small></div>` : ''}
123	    </li>`
124	      )
125	      .join('\n');
126	
127	    return `<!DOCTYPE html>
128	<html lang="en">
129	<head>
130	  <meta charset="UTF-8">
131	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
132	  <title>Static Site</title>
133	  <style>
134	    body {
135	      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
136	      line-height: 1.6;
137	      max-width: 800px;
138	      margin: 0 auto;
139	      padding: 20px;
140	      color: #333;
141	    }
