161	
162	  private escapeHtml(text: string): string {
163	    return text
164	      .replace(/&/g, '&amp;')
165	      .replace(/</g, '&lt;')
166	      .replace(/>/g, '&gt;')
167	      .replace(/"/g, '&quot;')
168	      .replace(/'/g, '&#39;');
169	  }
170	
171	  async build(): Promise<void> {
172	    this.ensureDir(this.outputDir);
173	
174	    const markdownFiles = this.getMarkdownFiles();
175	    const pages: PageMetadata[] = [];
176	
177	    for (const file of markdownFiles) {
178	      const filePath = path.join(this.contentDir, file);
179	      const content = fs.readFileSync(filePath, 'utf-8');
180	      const parsed = await parseMarkdown(content);
181	
182	      const title = parsed.frontmatter.title || file.replace('.md', '');
183	      const slug = file.replace('.md', '.html');
184	      const outputPath = path.join(this.outputDir, slug);
185	
186	      const templateName = parsed.frontmatter.template ? String(parsed.frontmatter.template) : undefined;
187	      const layoutName = parsed.frontmatter.layout ? String(parsed.frontmatter.layout) : undefined;
188	
189	      const pageHtml = this.renderPageWithTemplate(
190	        title,
191	        parsed.html,
192	        templateName,
193	        layoutName,
194	        parsed.frontmatter
195	      );
196	
197	      fs.writeFileSync(outputPath, pageHtml);
198	
199	      pages.push({
200	        filename: file,
201	        title,
202	        date: parsed.frontmatter.date ? String(parsed.frontmatter.date) : undefined,
203	        tags: Array.isArray(parsed.frontmatter.tags)
204	          ? parsed.frontmatter.tags.map((tag) => String(tag))
205	          : [],
206	        url: slug,
207	        template: templateName,
208	        layout: layoutName,
209	      });
210	    }
211	
212	    const indexPath = path.join(this.outputDir, 'index.html');
213	    fs.writeFileSync(indexPath, this.generateIndexHtml(pages));
214	
215	    console.log(`✓ Generated ${pages.length} page(s) to ${this.outputDir}`);
216	  }
217	}
