1	import { marked } from 'marked';
2	import matter from 'gray-matter';
3	import { Frontmatter, ParsedMarkdown } from './types.js';
4	// Note: .js extensions are required for ES modules
5	
6	function parseYamlFrontmatter(yamlString: string): Frontmatter {
7	  const frontmatter: Frontmatter = {};
8	
9	  const lines = yamlString.split('\n');
10	  for (const line of lines) {
11	    const trimmed = line.trim();
12	    if (!trimmed || trimmed.startsWith('#')) continue;
13	
14	    const colonIndex = trimmed.indexOf(':');
15	    if (colonIndex === -1) continue;
16	
17	    const key = trimmed.substring(0, colonIndex).trim();
18	    const valueStr = trimmed.substring(colonIndex + 1).trim();
19	
20	    if (key === 'tags') {
21	      if (valueStr) {
22	        frontmatter.tags = valueStr
23	          .split(',')
24	          .map((tag) => tag.trim())
25	          .filter((tag) => tag.length > 0);
26	      } else {
27	        frontmatter.tags = [];
28	      }
29	    } else if (key === 'title' || key === 'date') {
30	      frontmatter[key] = valueStr.replace(/^["']|["']$/g, '');
31	    } else if (valueStr) {
32	      frontmatter[key] = valueStr;
33	    }
34	  }
35	
36	  return frontmatter;
37	}
38	
39	export async function parseMarkdown(content: string): Promise<ParsedMarkdown> {
40	  let frontmatter: Frontmatter = {};
41	  let markdownContent = content;
42	
43	  // Try to parse YAML frontmatter manually first
44	  if (content.startsWith('---')) {
45	    const match = content.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
46	    if (match) {
47	      const yamlBlock = match[1];
48	      frontmatter = parseYamlFrontmatter(yamlBlock);
49	      markdownContent = match[2];
50	    }
51	  } else {
52	    // If no manual YAML, try gray-matter
53	    const matterResult = matter(content);
54	    frontmatter = matterResult.data as Frontmatter;
55	    markdownContent = matterResult.content;
56	
57	    // Convert any arrays to tags if needed
58	    if (frontmatter.tags && !Array.isArray(frontmatter.tags)) {
59	      if (typeof frontmatter.tags === 'string') {
60	        frontmatter.tags = (frontmatter.tags as string)
61	          .split(',')
62	          .map((tag: string) => tag.trim())
63	          .filter((tag: string) => tag.length > 0);
64	      }
65	    }
66	  }
67	
68	  const html = await marked(markdownContent);
69	
70	  return {
71	    frontmatter,
72	    content: markdownContent,
73	    html: html as string,
74	  };
75	}
