1	import * as fs from 'fs';
2	import * as path from 'path';
3	import Handlebars from 'handlebars';
4	
5	export class TemplateEngine {
6	  private templatesDir: string;
7	  private layoutsDir: string;
8	  private partialsDir: string;
9	  private cache: Map<string, HandlebarsTemplateDelegate> = new Map();
10	
11	  constructor(templatesDir: string) {
12	    this.templatesDir = templatesDir;
13	    this.layoutsDir = path.join(templatesDir, 'layouts');
14	    this.partialsDir = path.join(templatesDir, 'partials');
15	    this.registerPartials();
16	  }
17	
18	  private registerPartials(): void {
19	    if (!fs.existsSync(this.partialsDir)) {
20	      return;
21	    }
22	
23	    const partialFiles = fs.readdirSync(this.partialsDir).filter((f) => f.endsWith('.hbs'));
24	    for (const file of partialFiles) {
25	      const partialName = file.replace('.hbs', '');
26	      const partialContent = fs.readFileSync(path.join(this.partialsDir, file), 'utf-8');
27	      Handlebars.registerPartial(partialName, partialContent);
28	    }
29	  }
30	
31	  private getTemplate(templatePath: string): HandlebarsTemplateDelegate {
32	    if (this.cache.has(templatePath)) {
33	      return this.cache.get(templatePath)!;
34	    }
35	
36	    const content = fs.readFileSync(templatePath, 'utf-8');
37	    const template = Handlebars.compile(content);
38	    this.cache.set(templatePath, template);
39	    return template;
40	  }
41	
42	  renderTemplate(templatePath: string, data: Record<string, unknown>): string {
43	    if (!fs.existsSync(templatePath)) {
44	      throw new Error(`Template not found: ${templatePath}`);
45	    }
46	
47	    const template = this.getTemplate(templatePath);
48	    return template(data);
49	  }
50	
51	  renderLayout(layoutName: string, data: Record<string, unknown>): string {
52	    const layoutPath = path.join(this.layoutsDir, `${layoutName}.hbs`);
53	    return this.renderTemplate(layoutPath, data);
54	  }
55	
56	  renderPageTemplate(
57	    templateName: string,
58	    data: Record<string, unknown>,
59	    layoutName?: string
60	  ): string {
61	    const templatePath = path.join(this.templatesDir, `${templateName}.hbs`);
62	    let html = this.renderTemplate(templatePath, data);
63	
64	    if (layoutName) {
65	      const layoutData = {
66	        ...data,
67	        body: html,
68	      };
69	      html = this.renderLayout(layoutName, layoutData);
70	    }
71	
72	    return html;
73	  }
74	
75	  getDefaultLayoutPath(): string {
76	    return path.join(this.layoutsDir, 'default.hbs');
77	  }
78	
79	  hasLayout(layoutName: string): boolean {
80	    const layoutPath = path.join(this.layoutsDir, `${layoutName}.hbs`);
81	    return fs.existsSync(layoutPath);
82	  }
83	
84	  getAvailableTemplates(): string[] {
85	    if (!fs.existsSync(this.templatesDir)) {
86	      return [];
87	    }
88	
89	    return fs
90	      .readdirSync(this.templatesDir)
91	      .filter((f) => f.endsWith('.hbs') && !fs.statSync(path.join(this.templatesDir, f)).isDirectory())
92	      .map((f) => f.replace('.hbs', ''));
93	  }
94	
95	  getAvailableLayouts(): string[] {
96	    if (!fs.existsSync(this.layoutsDir)) {
97	      return [];
98	    }
99	
100	    return fs
101	      .readdirSync(this.layoutsDir)
102	      .filter((f) => f.endsWith('.hbs'))
103	      .map((f) => f.replace('.hbs', ''));
104	  }
105	}
