1	import * as http from 'http';
2	import * as fs from 'fs';
3	import * as path from 'path';
4	import * as chokidar from 'chokidar';
5	import { WebSocketServer } from 'ws';
6	import { SiteGenerator } from './generator.js';
7	
8	export interface DevServerOptions {
9	  contentDir: string;
10	  outputDir: string;
11	  templatesDir?: string;
12	  port?: number;
13	}
14	
15	export class DevServer {
16	  private contentDir: string;
17	  private outputDir: string;
18	  private templatesDir: string;
19	  private port: number;
20	  private httpServer: http.Server | null = null;
21	  private wsServer: WebSocketServer | null = null;
22	  private generator: SiteGenerator;
23	  private isBuilding = false;
24	
25	  constructor(options: DevServerOptions) {
26	    this.contentDir = options.contentDir;
27	    this.outputDir = options.outputDir;
28	    this.templatesDir = options.templatesDir || './templates';
29	    this.port = options.port || 3000;
30	    this.generator = new SiteGenerator({
31	      contentDir: this.contentDir,
32	      outputDir: this.outputDir,
33	      templatesDir: this.templatesDir,
34	    });
35	  }
36	
37	  private async rebuild(): Promise<void> {
38	    if (this.isBuilding) {
39	      return;
40	    }
41	
42	    this.isBuilding = true;
43	    try {
44	      console.log('🔄 Rebuilding...');
45	      await this.generator.build();
46	      console.log('✓ Rebuild complete');
47	      this.notifyClients();
48	    } catch (error) {
49	      console.error('Build error:', error instanceof Error ? error.message : String(error));
50	    } finally {
51	      this.isBuilding = false;
52	    }
53	  }
54	
55	  private notifyClients(): void {
56	    if (this.wsServer) {
57	      this.wsServer.clients.forEach((client) => {
58	        client.send(JSON.stringify({ type: 'reload' }));
59	      });
60	    }
61	  }
62	
63	  private injectLiveReloadScript(html: string): string {
64	    const liveReloadScript = `
65	<script>
66	(function() {
67	  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
68	  const ws = new WebSocket(protocol + '//' + window.location.host);
69	
70	  ws.onmessage = function(event) {
71	    const message = JSON.parse(event.data);
72	    if (message.type === 'reload') {
73	      console.log('[Live Reload] Reloading page...');
74	      window.location.reload();
75	    }
76	  };
77	
78	  ws.onerror = function(error) {
79	    console.error('[Live Reload] WebSocket error:', error);
80	  };
81	
82	  ws.onopen = function() {
83	    console.log('[Live Reload] Connected');
84	  };
85	})();
86	</script>
87	`;
88	    return html.replace('</body>', liveReloadScript + '</body>');
89	  }
90	
91	  private createHttpServer(): http.Server {
92	    return http.createServer((req, res) => {
93	      if (!req.url || req.method !== 'GET') {
94	        res.writeHead(405);
95	        res.end('Method Not Allowed');
96	        return;
97	      }
98	
99	      let filePath = req.url === '/' ? '/index.html' : req.url;
100	      filePath = path.join(this.outputDir, filePath);
101	
102	      try {
103	        if (!fs.existsSync(filePath)) {
104	          res.writeHead(404);
105	          res.end('Not Found');
106	          return;
107	        }
108	
109	        const stat = fs.statSync(filePath);
110	        if (stat.isDirectory()) {
111	          filePath = path.join(filePath, 'index.html');
112	          if (!fs.existsSync(filePath)) {
113	            res.writeHead(404);
114	            res.end('Not Found');
115	            return;
116	          }
117	        }
118	
119	        const content = fs.readFileSync(filePath, 'utf-8');
120	        const contentType = filePath.endsWith('.html') ? 'text/html' : 'application/octet-stream';
121	
122	        let responseContent = content;
123	        if (filePath.endsWith('.html')) {
124	          responseContent = this.injectLiveReloadScript(content);
125	        }
126	
127	        res.writeHead(200, { 'Content-Type': contentType });
128	        res.end(responseContent);
129	      } catch (error) {
130	        console.error('Server error:', error);
131	        res.writeHead(500);
132	        res.end('Internal Server Error');
133	      }
134	    });
135	  }
136	
137	  async start(): Promise<void> {
138	    this.httpServer = this.createHttpServer();
139	    this.wsServer = new WebSocketServer({ server: this.httpServer });
140	
141	    this.wsServer.on('connection', (ws) => {
142	      console.log('📡 Client connected');
143	      ws.send(JSON.stringify({ type: 'connected' }));
144	    });
145	
146	    const watcher = chokidar.watch([this.contentDir, this.templatesDir], {
147	      ignored: /(^|[\/\\])\.|node_modules/,
148	      awaitWriteFinish: {
149	        stabilityThreshold: 200,
150	        pollInterval: 100,
151	      },
152	    });
153	
154	    watcher.on('change', (filePath) => {
155	      console.log(`📝 File changed: ${filePath}`);
156	      this.rebuild();
157	    });
158	
159	    watcher.on('add', (filePath) => {
160	      console.log(`📝 File added: ${filePath}`);
161	      this.rebuild();
162	    });
163	
164	    watcher.on('unlink', (filePath) => {
165	      console.log(`📝 File removed: ${filePath}`);
166	      this.rebuild();
167	    });
168	
169	    return new Promise((resolve) => {
170	      this.httpServer!.listen(this.port, () => {
171	        console.log(`\n🚀 Dev server running on http://localhost:${this.port}`);
172	        console.log(`👀 Watching ${this.contentDir} and ${this.templatesDir} for changes...\n`);
173	      });
174	    });
175	  }
176	
177	  async stop(): Promise<void> {
178	    return new Promise((resolve) => {
179	      if (this.httpServer) {
180	        this.httpServer.close(() => {
