import { PageMetadata, BuildOptions, ParsedMarkdown, Frontmatter } from './types.js';

export interface PluginContext {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
  options?: Record<string, unknown>;
}

export interface FileContext {
  filename: string;
  filePath: string;
  content: string;
  parsed?: ParsedMarkdown;
  pageMetadata?: PageMetadata;
}

export interface Plugin {
  name: string;
  version?: string;

  onStart?(context: PluginContext): Promise<void>;
  beforeBuild?(context: PluginContext): Promise<void>;
  onFile?(context: PluginContext, file: FileContext): Promise<void>;
  afterBuild?(context: PluginContext, pages: PageMetadata[]): Promise<void>;
  onEnd?(context: PluginContext): Promise<void>;
}

export interface PluginConfig {
  plugins: (Plugin | string)[];
  [key: string]: unknown;
}

import { Plugin, PluginContext, FileContext } from './plugin.js';
import { PageMetadata } from './types.js';

export class PluginManager {
  private plugins: Plugin[] = [];

  constructor(plugins: Plugin[]) {
    this.plugins = plugins;
  }

  async onStart(context: PluginContext): Promise<void> {
    for (const plugin of this.plugins) {
      if (plugin.onStart) {
        await plugin.onStart(context);
      }
    }
  }

  async beforeBuild(context: PluginContext): Promise<void> {
    for (const plugin of this.plugins) {
      if (plugin.beforeBuild) {
        await plugin.beforeBuild(context);
      }
    }
  }

  async onFile(context: PluginContext, file: FileContext): Promise<void> {
    for (const plugin of this.plugins) {
      if (plugin.onFile) {
        await plugin.onFile(context, file);
      }
    }
  }

  async afterBuild(context: PluginContext, pages: PageMetadata[]): Promise<void> {
    for (const plugin of this.plugins) {
      if (plugin.afterBuild) {
        await plugin.afterBuild(context, pages);
      }
    }
  }

  async onEnd(context: PluginContext): Promise<void> {
    for (const plugin of this.plugins) {
      if (plugin.onEnd) {
        await plugin.onEnd(context);
      }
    }
  }

  getPlugins(): Plugin[] {
    return this.plugins;
  }

  addPlugin(plugin: Plugin): void {
    this.plugins.push(plugin);
  }

  removePlugin(pluginName: string): void {
    this.plugins = this.plugins.filter((p) => p.name !== pluginName);
  }

  getPlugin(pluginName: string): Plugin | undefined {
    return this.plugins.find((p) => p.name === pluginName);
  }
}

import { Plugin, PluginContext, FileContext } from '../plugin.js';
import { parseMarkdown } from '../parser.js';

export class MarkdownPlugin implements Plugin {
  name = 'markdown';
  version = '1.0.0';

  async onFile(context: PluginContext, file: FileContext): Promise<void> {
    if (!file.filename.endsWith('.md')) {
      return;
    }

    const parsed = await parseMarkdown(file.content);
    file.parsed = parsed;
  }
}

import * as fs from 'fs';
import * as path from 'path';
import { Plugin, PluginContext, FileContext } from '../plugin.js';
import { TemplateEngine } from '../template-engine.js';

export class TemplatePlugin implements Plugin {
  name = 'template';
  version = '1.0.0';
  private templateEngine: TemplateEngine | null = null;

  async beforeBuild(context: PluginContext): Promise<void> {
    if (context.templatesDir && fs.existsSync(context.templatesDir)) {
      this.templateEngine = new TemplateEngine(context.templatesDir);
    }
  }

  async onFile(context: PluginContext, file: FileContext): Promise<void> {
    if (!file.parsed) {
      return;
    }

    const title = file.parsed.frontmatter.title || file.filename.replace('.md', '');
    const templateName = file.parsed.frontmatter.template
      ? String(file.parsed.frontmatter.template)
      : undefined;
    const layoutName = file.parsed.frontmatter.layout ? String(file.parsed.frontmatter.layout) : undefined;

    file.pageMetadata = {
      filename: file.filename,
      title,
      date: file.parsed.frontmatter.date ? String(file.parsed.frontmatter.date) : undefined,
      tags: Array.isArray(file.parsed.frontmatter.tags)
        ? file.parsed.frontmatter.tags.map((tag) => String(tag))
        : [],
      url: file.filename.replace('.md', '.html'),
      template: templateName,
      layout: layoutName,
    };

    file.html = this.renderPageWithTemplate(title, file.parsed.html, templateName, layoutName, file.parsed.frontmatter);
  }

  private renderPageWithTemplate(
    title: string,
    content: string,
    templateName?: string,
    layoutName?: string,
    data?: Record<string, unknown>
  ): string {
    if (!this.templateEngine) {
      return this.generatePageHtml(title, content);
    }

    const pageData = {
      title: this.escapeHtml(title),
      content,
      ...data,
    };

    const template = templateName || 'page';
    const layout = layoutName || 'default';

    try {
      if (this.templateEngine.hasLayout(layout)) {
        return this.templateEngine.renderPageTemplate(template, pageData, layout);
      }
    } catch {
      // Fall back to default HTML if template rendering fails
    }

    return this.generatePageHtml(title, content);
  }

  private generatePageHtml(title: string, content: string): string {
    return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${this.escapeHtml(title)}</title>
  <style>
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
      line-height: 1.6;
      max-width: 800px;
      margin: 0 auto;
      padding: 20px;
      color: #333;
    }
    h1, h2, h3, h4, h5, h6 { margin-top: 1.5em; }
    code {
      background: #f0f0f0;
      padding: 2px 6px;
      border-radius: 3px;
      font-family: 'Courier New', monospace;
    }
    pre {
      background: #f5f5f5;
      padding: 10px;
      border-radius: 5px;
      overflow-x: auto;
    }
    pre code { background: none; padding: 0; }
    a { color: #0066cc; text-decoration: none; }
    a:hover { text-decoration: underline; }
    .nav { margin-bottom: 20px; }
    .nav a { margin-right: 15px; }
  </style>
</head>
<body>
  <div class="nav">
    <a href="index.html">← Home</a>
  </div>
  <h1>${this.escapeHtml(title)}</h1>
  <div>${content}</div>
</body>
</html>`;
  }

  private escapeHtml(text: string): string {
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }
}

import * as http from 'http';
import * as fs from 'fs';
import * as path from 'path';
import * as chokidar from 'chokidar';
import { WebSocketServer } from 'ws';
import { Plugin, PluginContext } from '../plugin.js';

export interface DevServerOptions {
  port?: number;
  onRebuild?: () => Promise<void>;
}

export class DevServerPlugin implements Plugin {
  name = 'dev-server';
  version = '1.0.0';
  private httpServer: http.Server | null = null;
  private wsServer: WebSocketServer | null = null;
  private options: DevServerOptions;
  private watcher: chokidar.FSWatcher | null = null;

  constructor(options: DevServerOptions = {}) {
    this.options = options;
  }

  async onStart(context: PluginContext): Promise<void> {
    this.setupHttpServer(context);
  }

  async onEnd(context: PluginContext): Promise<void> {
    await this.stop();
  }

  private setupHttpServer(context: PluginContext): void {
    const port = this.options.port || 3000;
    const outputDir = context.outputDir;

    this.httpServer = http.createServer((req, res) => {
      if (!req.url || req.method !== 'GET') {
        res.writeHead(405);
        res.end('Method Not Allowed');
        return;
      }

      let filePath = req.url === '/' ? '/index.html' : req.url;
      filePath = path.join(outputDir, filePath);

      try {
        if (!fs.existsSync(filePath)) {
          res.writeHead(404);
          res.end('Not Found');
          return;
        }

        const stat = fs.statSync(filePath);
        if (stat.isDirectory()) {
          filePath = path.join(filePath, 'index.html');
          if (!fs.existsSync(filePath)) {
            res.writeHead(404);
            res.end('Not Found');
            return;
          }
        }

        const content = fs.readFileSync(filePath, 'utf-8');
        const contentType = filePath.endsWith('.html') ? 'text/html' : 'application/octet-stream';

        let responseContent = content;
        if (filePath.endsWith('.html')) {
          responseContent = this.injectLiveReloadScript(content);
        }

        res.writeHead(200, { 'Content-Type': contentType });
        res.end(responseContent);
      } catch (error) {
        console.error('Server error:', error);
        res.writeHead(500);
        res.end('Internal Server Error');
      }
    });

    this.wsServer = new WebSocketServer({ server: this.httpServer });

    this.wsServer.on('connection', (ws) => {
      console.log('📡 Client connected');
      ws.send(JSON.stringify({ type: 'connected' }));
    });

    this.setupWatcher(context);

    this.httpServer.listen(port, () => {
      console.log(`\n🚀 Dev server running on http://localhost:${port}`);
      console.log(`👀 Watching ${context.contentDir} and ${context.templatesDir} for changes...\n`);
    });
  }

  private setupWatcher(context: PluginContext): void {
    this.watcher = chokidar.watch([context.contentDir, context.templatesDir || ''], {
      ignored: /(^|[\/\\])\.|node_modules/,
      awaitWriteFinish: {
        stabilityThreshold: 200,
        pollInterval: 100,
      },
    });

    let isBuilding = false;

    const rebuild = async () => {
      if (isBuilding) {
        return;
      }

      isBuilding = true;
      try {
        console.log('🔄 Rebuilding...');
        if (this.options.onRebuild) {
          await this.options.onRebuild();
        }
        console.log('✓ Rebuild complete');
        this.notifyClients();
      } catch (error) {
        console.error('Build error:', error instanceof Error ? error.message : String(error));
      } finally {
        isBuilding = false;
      }
    };

    this.watcher.on('change', (filePath) => {
      console.log(`📝 File changed: ${filePath}`);
      rebuild();
    });

    this.watcher.on('add', (filePath) => {
      console.log(`📝 File added: ${filePath}`);
      rebuild();
    });

    this.watcher.on('unlink', (filePath) => {
      console.log(`📝 File removed: ${filePath}`);
      rebuild();
    });
  }

  private injectLiveReloadScript(html: string): string {
    const liveReloadScript = `
<script>
(function() {
  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
  const ws = new WebSocket(protocol + '//' + window.location.host);

  ws.onmessage = function(event) {
    const message = JSON.parse(event.data);
    if (message.type === 'reload') {
      console.log('[Live Reload] Reloading page...');
      window.location.reload();
    }
  };

  ws.onerror = function(error) {
    console.error('[Live Reload] WebSocket error:', error);
  };

  ws.onopen = function() {
    console.log('[Live Reload] Connected');
  };
})();
</script>
`;
    return html.replace('</body>', liveReloadScript + '</body>');
  }

  private notifyClients(): void {
    if (this.wsServer) {
      this.wsServer.clients.forEach((client) => {
        client.send(JSON.stringify({ type: 'reload' }));
      });
    }
  }

  async stop(): Promise<void> {
    return new Promise((resolve) => {
      if (this.watcher) {
        this.watcher.close();
      }
      if (this.httpServer) {
        this.httpServer.close(() => {
          console.log('Dev server stopped');
          resolve();
        });
      } else {
        resolve();
      }
    });
  }
}

